    receive() external payable {}

    function run(uint initVal, address logAddr) public payable {
        c.SetMinSum(initVal); if (__ESBMC_reverted()) return;
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinReverted;
        c.SetMinSum(initVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }
        bool setLogReverted;
        c.SetLogFile(address(0xdead)); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
