pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 initVal, address logAddr) internal {
        try c.SetMinSum(initVal) {} catch { return; }
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        try c.SetLogFile(logAddr) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool setMinReverted;
        try c.SetMinSum(initVal) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }
        bool setLogReverted;
        try c.SetLogFile(address(0xdead)) {
            setLogReverted = false;
        } catch {
            setLogReverted = true;
        }
        assertTrue(setMinReverted && setLogReverted && c.MinSum() == beforeMinSum);
    }

    function testFuzz_run(uint256 initVal, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(initVal, logAddr);
    }

    receive() external payable {}
}
